import{_ as a,c as s,o as l,a3 as e}from"./chunks/framework.CoV49S2T.js";const k=JSON.parse('{"title":"疑難排解","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/troubleshooting.md","filePath":"zh-TW/guide/troubleshooting.md","lastUpdated":1787284674000}'),t={name:"zh-TW/guide/troubleshooting.md"};function o(n,i,r,h,p,d){return l(),s("div",null,[...i[0]||(i[0]=[e(`<h1 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to &quot;疑難排解&quot;">​</a></h1><p>本頁彙整 ClipboxAI 在 macOS 上的常見問題及其解決方式。</p><h2 id="應用程式無法啟動或在啟動時崩潰" tabindex="-1">應用程式無法啟動或在啟動時崩潰 <a class="header-anchor" href="#應用程式無法啟動或在啟動時崩潰" aria-label="Permalink to &quot;應用程式無法啟動或在啟動時崩潰&quot;">​</a></h2><ol><li>確認你的 macOS 版本符合最低要求（macOS 14 Sonoma 以上）。</li><li>退出並重新啟動應用程式。</li><li>重新啟動你的 Mac。</li><li><s>若從 GitHub Releases 下載，請嘗試最新或已公證的建置版本。</s></li><li>若問題持續，請蒐集日誌（如下方）並開啟一個 issue。</li></ol><h2 id="剪貼簿歷史沒有捕捉到複製內容" tabindex="-1">剪貼簿歷史沒有捕捉到複製內容 <a class="header-anchor" href="#剪貼簿歷史沒有捕捉到複製內容" aria-label="Permalink to &quot;剪貼簿歷史沒有捕捉到複製內容&quot;">​</a></h2><p>症狀：新的複製內容沒有出現在歷史面板中。</p><p>檢查清單：</p><ol><li>確認應用程式正在執行，且其選單列圖示可見。</li><li>確認 <strong>Clipboard monitoring（剪貼簿監控）</strong> 已在 <strong>Settings → Privacy / General（設定 → 隱私／一般）</strong> 中啟用。</li><li>應用程式需要相關的 macOS 權限才能在背景讀取剪貼板——請參見<a href="/zh-TW/guide/permissions.html">權限</a>。</li><li>某些應用程式（密碼管理器、安全輸入欄位）會刻意封鎖剪貼簿存取；此為預期行為。</li></ol><h2 id="雲端-ai-動作沒有回傳結果" tabindex="-1">雲端 AI 動作沒有回傳結果 <a class="header-anchor" href="#雲端-ai-動作沒有回傳結果" aria-label="Permalink to &quot;雲端 AI 動作沒有回傳結果&quot;">​</a></h2><p>症狀：某個 AI 動作失敗、卡住，或顯示設定錯誤。</p><p>檢查清單：</p><ol><li>開啟 <strong>Settings → AI（設定 → AI）</strong>，確認已選取供應商並輸入了 key。</li><li>驗證該 key 對該供應商有效，且有額度／點數。</li><li>檢查你的網路連線——雲端 AI 需要網際網路存取。</li><li>確認所選的模型名稱對該供應商而言是正確的。</li><li>若 AI 工具視窗中仍出現設定橫幅，表示 key 未儲存至 Keychain；請重新輸入。</li></ol><h2 id="marketplace-安裝沒有加入動作" tabindex="-1">Marketplace 安裝沒有加入動作 <a class="header-anchor" href="#marketplace-安裝沒有加入動作" aria-label="Permalink to &quot;Marketplace 安裝沒有加入動作&quot;">​</a></h2><p>症狀：點擊 <strong>Install（安裝）</strong> 沒有任何反應，或應用程式沒有開啟。</p><p>檢查清單：</p><ol><li>深層連結 <code>clipboxai://install?action=&lt;id&gt;</code> 必須由已安裝的應用程式處理——請確認 ClipboxAI 已安裝並正在執行。</li><li>若你的瀏覽器封鎖該深層連結，請複製它並手動開啟，或從應用程式內的 <strong>Marketplace</strong> 分頁安裝。</li><li>確認該動作 ID 仍已在 marketplace 中發佈。</li></ol><h2 id="重設應用程式" tabindex="-1">重設應用程式 <a class="header-anchor" href="#重設應用程式" aria-label="Permalink to &quot;重設應用程式&quot;">​</a></h2><p>若要重設設定並清除本地資料：</p><ol><li>退出 ClipboxAI。</li><li>移除容器（這會刪除歷史紀錄與設定）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><ol start="3"><li>重新開啟應用程式並重新設定。若需要，Keychain 中的 API key 必須在 <strong>Keychain Access</strong> 中另行移除。</li></ol><h2 id="如何蒐集除錯日誌" tabindex="-1">如何蒐集除錯日誌 <a class="header-anchor" href="#如何蒐集除錯日誌" aria-label="Permalink to &quot;如何蒐集除錯日誌&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy logs to Desktop for sharing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard/Data/Library/Logs/Clipboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">AI/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>接著在 <a href="https://github.com/clipboxAI" target="_blank" rel="noreferrer">GitHub</a> 開啟一個 issue 並附上日誌。</p><h2 id="回報問題" tabindex="-1">回報問題 <a class="header-anchor" href="#回報問題" aria-label="Permalink to &quot;回報問題&quot;">​</a></h2><p>開啟 issue 時，請包含：</p><ul><li>macOS 版本（Apple 選單 → About This Mac）</li><li>ClipboxAI 版本（應用程式選單 → About）</li><li>重現步驟</li><li>日誌（見上方）</li></ul><p>這有助於維護者更快地找出並修復問題。</p>`,28)])])}const g=a(t,[["render",o]]);export{k as __pageData,g as default};
